package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class InverseProductFactsTest {
 @Test public void everyRelatedFactAndBothDirectionsComeFromPublicOperands(){Set<String> seen=new HashSet<>();Checker checker=new Checker();int count=0;for(int a:new int[]{2,3,5,10})for(int b=1;b<=10;b++){if(a*b<10)continue;for(int mode=0;mode<2;mode++){count++;Question q=InverseProductFacts.make(a,b,mode);assertTrue(seen.add(q.signature()));int result=mode==0?b:a*b;q.answers=new String[]{"poison"};q.expression="poison";assertTrue(checker.check(q,List.of(),List.of(""+result)).correct());assertEquals(Checker.Status.WRONG_ANSWER,checker.check(q,List.of(),List.of(""+(result+1))).status);HelpPlan h=HelpPlan.forQuestion(q);assertEquals(4,h.size());assertFalse(h.canTransfer());int[] entries={a*b,a,b,result};for(int i=0;i<4;i++)assertTrue(h.step(i).accepts(""+entries[i]));}}
 assertEquals(64,count);assertEquals(count,InverseProductFacts.DOMAIN.size());for(String invalid:List.of("아는 계산: 2 × 5 = 11\n11 ÷ 2 = □","아는 계산: 10 ÷ 2 = 5\n2 × 4 = □","아는 계산: 6 × 2 = 12\n12 ÷ 6 = □","아는 계산: 2 × 2 = 4\n4 ÷ 2 = □")){Question q=new Question(InverseProductFacts.ID,invalid,"","0");assertNull(InverseProductFacts.read(q));assertEquals(Checker.Status.INPUT_NEEDED,checker.check(q,List.of(),List.of("0")).status);}
 }
 @Test public void fullFreshSupplyOnlyInReviewedGradeThree(){var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();assertTrue(pack.inGrade(InverseProductFacts.ID,3));assertFalse(pack.inGrade(InverseProductFacts.ID,2));assertFalse(Curriculum.inCurriculum(InverseProductFacts.SKILL,2022));Generator g=new Generator(new Random(207));List<String> recent=new ArrayList<>();CurriculumLimits limits=GlobalCurriculum.limits(pack.id,InverseProductFacts.ID,3);for(int i=0;i<64;i++){Question q=g.next(InverseProductFacts.ID,recent,false,limits);assertTrue(limits.allows(q));assertFalse(recent.contains(q.signature()));recent.add(q.signature());assertNotNull(InverseProductFacts.read(q));}}
}
